ALTER TABLE public.user_profiles ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
ALTER TABLE public.workspace_members ADD COLUMN IF NOT EXISTS removed_at timestamptz;
ALTER TABLE public.message_threads ADD COLUMN IF NOT EXISTS related_person_id uuid;
ALTER TABLE public.message_threads ADD COLUMN IF NOT EXISTS related_workspace_id uuid;
CREATE OR REPLACE FUNCTION public.admin_user_removal_plan(_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.user_profiles; m boolean; n bigint:=0; k bigint; c record; BEGIN SELECT * INTO p FROM public.user_profiles WHERE user_id=_user; IF NOT FOUND OR public.is_master_admin(_user) THEN RAISE EXCEPTION 'Protected or unavailable account'; END IF; m:=public.is_master_admin(auth.uid()); IF NOT public.admin_can('people','manage') THEN RAISE EXCEPTION 'Manage permission required'; END IF; IF NOT m AND (NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE user_id=_user) OR EXISTS(SELECT 1 FROM public.workspace_members WHERE user_id=_user AND NOT public.admin_can_account(workspace_id))) THEN RAISE EXCEPTION 'Account scope required'; END IF; FOR c IN SELECT table_name,column_name FROM information_schema.columns WHERE table_schema='public' AND data_type='uuid' AND table_name NOT IN ('user_profiles','workspace_members') LOOP EXECUTE format('SELECT count(*) FROM public.%I WHERE %I=$1',c.table_name,c.column_name) INTO k USING _user; n:=n+k; END LOOP; RETURN jsonb_build_object('mode',CASE WHEN m AND n=0 THEN 'delete' ELSE 'deactivate' END,'master',m,'protected_records',n,'mfn_id',p.mfn_id); END $$;
REVOKE ALL ON FUNCTION public.admin_user_removal_plan(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_user_removal_plan(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_finalize_user_removal(_user uuid,_reason text,_mode text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE plan jsonb; BEGIN plan:=public.admin_user_removal_plan(_user); IF length(trim(_reason))<5 OR length(_reason)>500 OR plan->>'mode'<>_mode THEN RAISE EXCEPTION 'Review account state and reason'; END IF; UPDATE public.user_profiles SET status='suspended',deleted_at=now(),display_name=CASE WHEN _mode='delete' THEN 'Deleted user' ELSE display_name END,phone=CASE WHEN _mode='delete' THEN NULL ELSE phone END WHERE user_id=_user; UPDATE public.workspace_members SET removed_at=now(),can_manage_trips=false,can_create_requests=false,can_view_workspace_requests=false,can_message_for_workspace=false,record_permissions='{}' WHERE user_id=_user; PERFORM public.log_staff_action('user_access_removed','person',plan->>'mfn_id',jsonb_build_object('reason',_reason,'mode',_mode,'protected_records',plan->'protected_records')); END $$;
REVOKE ALL ON FUNCTION public.admin_finalize_user_removal(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_finalize_user_removal(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_user_retention_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user NOT IN ('postgres','service_role') THEN NEW.deleted_at:=OLD.deleted_at; END IF; IF public.is_master_admin(OLD.user_id) AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'Master Admin cannot be deactivated'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_user_retention_fields BEFORE UPDATE ON public.user_profiles FOR EACH ROW EXECUTE FUNCTION public.guard_user_retention_fields();
CREATE OR REPLACE FUNCTION public.guard_membership_removal() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user NOT IN ('postgres','service_role') THEN NEW.removed_at:=OLD.removed_at; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_membership_removal BEFORE UPDATE ON public.workspace_members FOR EACH ROW EXECUTE FUNCTION public.guard_membership_removal();
CREATE OR REPLACE FUNCTION public.admin_message_person(_user uuid,_workspace uuid,_body text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF NOT public.admin_can('people','read') OR NOT public.admin_can('messaging','manage') OR _user=auth.uid() OR NOT EXISTS(SELECT 1 FROM public.user_profiles WHERE user_id=_user AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Messaging permission required'; END IF; IF _workspace IS NOT NULL THEN IF NOT public.admin_can_account(_workspace) OR NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE user_id=_user AND workspace_id=_workspace AND removed_at IS NULL) THEN RAISE EXCEPTION 'Account scope required'; END IF; ELSIF NOT public.is_master_admin(auth.uid()) THEN RAISE EXCEPTION 'Workspace required'; END IF; IF length(trim(_body))=0 OR length(_body)>5000 THEN RAISE EXCEPTION 'Message required'; END IF; SELECT t.id INTO tid FROM public.message_threads t WHERE t.created_by=auth.uid() AND t.related_person_id=_user AND t.related_workspace_id IS NOT DISTINCT FROM _workspace AND (SELECT count(*) FROM public.thread_participants WHERE thread_id=t.id)=2 LIMIT 1; IF tid IS NULL THEN INSERT INTO public.message_threads(created_by,subject,related_person_id,related_workspace_id) VALUES(auth.uid(),'Account conversation',_user,_workspace) RETURNING id INTO tid; INSERT INTO public.thread_participants(thread_id,user_id) VALUES(tid,auth.uid()),(tid,_user); END IF; INSERT INTO public.messages(thread_id,sender_id,body) VALUES(tid,auth.uid(),trim(_body)); PERFORM public.log_staff_action('account_message_sent','person',(SELECT mfn_id FROM public.user_profiles WHERE user_id=_user),jsonb_build_object('thread_id',tid,'workspace_id',_workspace)); RETURN tid; END $$;
REVOKE ALL ON FUNCTION public.admin_message_person(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_message_person(uuid,uuid,text) TO authenticated;